changeSet.sql:
ALTER TABLE apartment ADD COLUMN IF NOT EXISTS plan_key VARCHAR(512);
ALTER TABLE apartment ADD COLUMN IF NOT EXISTS entrance_plan_key VARCHAR(512);

UPDATE apartment
SET plan_key = 'apartments/' || id || '/' || id || '.jpg',
    entrance_plan_key = 'apartments/' || id || '/' || id || '-entrance.jpg';

ALTER TABLE apartment ALTER COLUMN plan_key SET NOT NULL;
ALTER TABLE apartment ALTER COLUMN entrance_plan_key SET NOT NULL;
